USE ROLE SECURITYADMIN;
CREATE ROLE IF NOT EXISTS SUPERATOM_READER;
GRANT USAGE ON WAREHOUSE YOUR_WAREHOUSE TO ROLE SUPERATOM_READER;
GRANT USAGE ON DATABASE YOUR_DATABASE TO ROLE SUPERATOM_READER;
GRANT USAGE ON ALL SCHEMAS IN DATABASE YOUR_DATABASE TO ROLE SUPERATOM_READER;
GRANT SELECT ON ALL TABLES IN DATABASE YOUR_DATABASE TO ROLE SUPERATOM_READER;
GRANT SELECT ON ALL VIEWS IN DATABASE YOUR_DATABASE TO ROLE SUPERATOM_READER;
GRANT SELECT ON FUTURE TABLES IN DATABASE YOUR_DATABASE TO ROLE SUPERATOM_READER;
GRANT SELECT ON FUTURE VIEWS IN DATABASE YOUR_DATABASE TO ROLE SUPERATOM_READER;
CREATE USER IF NOT EXISTS SUPERATOM TYPE = SERVICE DEFAULT_ROLE = SUPERATOM_READER DEFAULT_WAREHOUSE = YOUR_WAREHOUSE;
GRANT ROLE SUPERATOM_READER TO USER SUPERATOM;

CREATE NETWORK RULE IF NOT EXISTS SUPERATOM_ENGINE MODE = INGRESS TYPE = IPV4 VALUE_LIST = ('THE_ENGINE_ADDRESS');
CREATE NETWORK POLICY IF NOT EXISTS SUPERATOM_ENGINE ALLOWED_NETWORK_RULE_LIST = ('SUPERATOM_ENGINE');
ALTER USER SUPERATOM SET NETWORK_POLICY = SUPERATOM_ENGINE;
ALTER USER SUPERATOM ADD PROGRAMMATIC ACCESS TOKEN SUPERATOM_TOKEN ROLE_RESTRICTION = 'SUPERATOM_READER' DAYS_TO_EXPIRY = 365;
